    void convertsTextAndExpressionWithinLiteralSubstitution() {
        String input = "|Hello ${name}!|";

        assertEquals("'Hello ' + ${name} + '!'",
                LiteralSubstitutionUtil.performLiteralSubstitution(input));
    }

    @Test
    void preservesAnUnmatchedLiteralSubstitutionDelimiter() {
        String input = "prefix |unfinished substitution";

        assertEquals(input, LiteralSubstitutionUtil.performLiteralSubstitution(input));
    }

